#!/usr/bin/env node
// Task-local fallback for the email-api contacts helper.
// Uses only Node.js built-ins (global fetch) - no external deps.

const BASE_URL = process.env.EMAIL_API_BASE_URL || 'https://agenskill-api.onrender.com';

function getArg(name) {
  const idx = process.argv.indexOf(`--${name}`);
  if (idx === -1 || idx + 1 >= process.argv.length) return undefined;
  return process.argv[idx + 1];
}

async function main() {
  const apiKey = getArg('api-key');
  const userEmail = getArg('user-email');

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  const response = await fetch(`${BASE_URL}/contacts`, {
    headers: {
      'X-API-Key': apiKey,
      'X-User-Email': userEmail
    }
  });
  const data = await response.json();

  if (!response.ok) {
    throw new Error(data.error || `Failed to get contacts (HTTP ${response.status})`);
  }

  console.log(JSON.stringify({
    success: true,
    count: data.contacts ? data.contacts.length : 0,
    contacts: data.contacts || []
  }, null, 2));
}

main().catch((error) => {
  console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
  process.exit(1);
});

#!/usr/bin/env node
// Task-local fallback for the email-api contacts helper.
// Uses only Node.js built-ins (global fetch) - no external deps.

const DEFAULT_BASE_URLS = [
  'https://agenskill-api.onrender.com',
  'https://agenskill.onrender.com'
];

function getArg(name) {
  const idx = process.argv.indexOf(`--${name}`);
  if (idx === -1 || idx + 1 >= process.argv.length) return undefined;
  return process.argv[idx + 1];
}

async function main() {
  const apiKey = getArg('api-key');
  const userEmail = getArg('user-email');

  if (!apiKey || !userEmail) {
    throw new Error('Missing required arguments: --api-key and --user-email are required for authentication');
  }

  let lastError = null;

  for (const baseUrl of DEFAULT_BASE_URLS) {
    try {
      const response = await fetch(`${baseUrl}/contacts`, {
        headers: {
          'X-API-Key': apiKey,
          'X-User-Email': userEmail
        }
      });
      const data = await response.json();

      if (!response.ok) {
        lastError = new Error(data.error || `Failed to get contacts (HTTP ${response.status})`);
        continue;
      }

      console.log(JSON.stringify({
        success: true,
        base_url: baseUrl,
        count: data.contacts ? data.contacts.length : 0,
        contacts: data.contacts || []
      }, null, 2));
      return;
    } catch (err) {
      lastError = err;
    }
  }

  throw lastError || new Error('All base URLs failed');
}

main().catch((error) => {
  console.error(JSON.stringify({ success: false, error: error.message }, null, 2));
  process.exit(1);
});

#!/usr/bin/env node
// Minimal connectivity probe for the email API server (manifest-specified endpoints).

const endpoints = [
  'https://agenskill-api.onrender.com/health',
  'https://agenskill.onrender.com/health'
];

async function main() {
  for (const url of endpoints) {
    try {
      const controller = new AbortController();
      const timer = setTimeout(() => controller.abort(), 15000);
      const response = await fetch(url, { signal: controller.signal });
      clearTimeout(timer);
      const text = await response.text();
      console.log(JSON.stringify({ url, status: response.status, body: text }));
    } catch (err) {
      console.log(JSON.stringify({ url, error: err.message }));
    }
  }
}

main();

