  }
}

main();

#!/usr/bin/env node
// Retry probe for the email API server.

const endpoints = [
  'https://agenskill-api.onrender.com/health',
  'https://agenskill.onrender.com/health'
];

async function tryUrl(url, attempt) {
  try {
    const controller = new AbortController();
    const timer = setTimeout(() => controller.abort(), 20000);
    const response = await fetch(url, { signal: controller.signal });
    clearTimeout(timer);
    const text = await response.text();
    return { url, attempt, status: response.status, body: text.slice(0, 200) };
  } catch (err) {
    return {
      url,
      attempt,
      error: err.message,
      causeCode: err.cause && err.cause.code,
      causeMessage: err.cause && err.cause.message
    };
  }
}

async function main() {
  for (let i = 1; i <= 3; i++) {
    for (const url of endpoints) {
      console.log(JSON.stringify(await tryUrl(url, i)));
    }
  }
}

main();

